<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admissions CRM</title><style>body{font-family:system-ui;margin:0;background:#f4f7fb;color:#172033}.shell{max-width:1200px;margin:auto;padding:24px 16px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:16px}.v{font-size:28px;font-weight:800}input,select,button{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}a{text-decoration:none}table{width:100%;background:#fff;border-collapse:collapse;margin-top:14px}th,td{padding:10px;border-bottom:1px solid #edf2f7;text-align:left;font-size:14px}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}table{display:block;overflow:auto}}</style></head><body><div class="shell"><p><a href="{{ route('tagore.dashboard') }}">← Dashboard</a></p><h1>Admissions CRM</h1><p>Fast lead pipeline for admissions, follow-ups and calling.</p><div class="cards">@foreach([['Total','total'],['New','new'],['Follow-up','follow_up'],['Due today','due_today']] as [$l,$k])<div class="card"><small>{{ $l }}</small><div class="v">{{ $stats[$k] }}</div></div>@endforeach</div><form style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap"><input name="q" value="{{ request('q') }}" placeholder="Student / parent / mobile"><select name="status"><option value="">All</option>@foreach(['new','contacted','follow_up','qualified','admitted','lost'] as $s)<option value="{{ $s }}" @selected(request('status')===$s)>{{ ucfirst(str_replace('_',' ',$s)) }}</option>@endforeach</select><button>Filter</button><a href="{{ route('tagore.admissions.create') }}">+ New lead</a></form><table><tr><th>Lead</th><th>Student</th><th>Parent</th><th>Mobile</th><th>Class</th><th>Status</th><th>Follow-up</th></tr>@forelse($leads as $lead)<tr><td><a href="{{ route('tagore.admissions.show',$lead) }}">{{ $lead->lead_no }}</a></td><td>{{ $lead->student_